INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente submetido a cirurgia abdominal de grande porte via laparotomia mediana desenvolve febre baixa e pequena quantidade de derrame pleural bilateral no 2º dia pós-operatório. Ele está estável, sem dispneia. RX mostra atelectasias laminares nas bases. Qual a explicação mais provável e a melhor conduta?", "options": {"a": "TEP pós-operatório; solicitar Angio-TC de urgência.", "b": "Quilotórax por lesão inadvertida do ducto torácico; dieta zero.", "c": "Derrame pleural simpático secundário à cirurgia abdominal e atelectasia; fisioterapia respiratória.", "d": "Empiema por translocação bacteriana; realizar toracentese imediata.", "e": "Pneumonia nosocomial precoce; iniciar meropenem."}, "answer": "c", "rationale": "É muito comum a ocorrência de pequenos derrames pleurais no pós-operatório imediato de cirurgias abdominais superiores. Eles ocorrem por irritação diafragmática, manipulação de fluidos ou atelectasias de base. Se o paciente está estável, a conduta é expectante e focada na reexpansão pulmonar com fisioterapia.", "option_rationales": {"a": "Incorreta. Embora possível, o quadro é muito típico de reação pós-cirúrgica benigna.", "b": "Incorreta. Cirurgia abdominal dificilmente lesa o ducto torácico a ponto de dar derrame bilateral no 2º dia sem outras queixas.", "c": "Correta. Derrame reativo comum em cirurgias abdominais.", "d": "Incorreta. Empiema não surge tão rápido e sem foco infectado importante.", "e": "Incorreta. Quadro clínico leve demais para pneumonia grave."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia", "Pós-operatório", "Derrame Reativo"]}', 50, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A causa mais comum de derrame pleural transudativo em pacientes hospitalizados é:", "options": {"a": "Cirrose Hepática.", "b": "Hipotireoidismo.", "c": "Síndrome Nefrótica.", "d": "Insuficiência Cardíaca Congestiva.", "e": "Embolia Pulmonar."}, "answer": "d", "rationale": "A Insuficiência Cardíaca Congestiva (ICC) é disparada a causa mais comum de transudatos pleurais no mundo. Estima-se que mais de 500.000 casos ocorram anualmente apenas nos EUA.", "option_rationales": {"a": "Incorreta. Comum, mas menos que a ICC.", "b": "Incorreta. Causa rara de derrame isolado significativo.", "c": "Incorreta. Causa de transudato, mas menos frequente.", "d": "Incorreta.", "e": "Incorreta. TEP causa exsudato em 75-80% das vezes e transudato em apenas 20%."}, "difficulty": "facil", "tags": ["Pneumologia", "Epidemiologia", "ICC", "Transudato"]}', 51, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 38 anos apresenta febre alta diária em picos, odinofagia, artralgias e rash cutâneo fugaz (cor salmão) no tronco durante os episódios febris. Ao exame físico, observa-se esplenomegalia. Laboratório mostra leucocitose importante (neutrofilia) e ferritina sérica de 8.000 ng/mL. A radiografia de tórax revela pequeno derrame pleural bilateral (exsudato neutrofílico). Qual o diagnóstico mais provável?", "options": {"a": "Tuberculose Miliar.", "b": "Febre Reumática.", "c": "Doença de Still do Adulto.", "d": "Linfoma de Hodgkin.", "e": "Lúpus Eritematoso Sistêmico."}, "answer": "c", "rationale": "A Doença de Still do Adulto é uma síndrome autoinflamatória caracterizada pela tríade: febre alta, artrite/artralgia e rash salmão evanescente. A ferritina muito elevada e a leucocitose neutrofílica são marcos laboratoriais. O envolvimento de serosites (pleurite e pericardite) ocorre em cerca de 30-40% dos casos.", "option_rationales": {"a": "Incorreta. Embora cause febre e serosite, não explica o rash fugaz e a ferritina tão alta.", "b": "Incorreta. Quadro clínico e perfil laboratorial distintos.", "c": "Correta. Descrição clássica da doença e seus achados pleurais.", "d": "Incorreta. O rash e a ferritina astronômica favorecem Still.", "e": "Incorreta. Lúpus costuma ter leucopenia e outros anticorpos positivos; o rash é malar e fixo."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Doença de Still", "Ferritina"]}', 52, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 35 anos apresenta um derrame pleural volumoso recorrente. A análise do líquido revela: Exsudato linfocítico (95%), Glicose 80 mg/dL, ADA 22 U/L, Citologia oncótica negativa. O paciente apresenta também ascite e linfedema de membros inferiores de surgimento espontâneo. Observa-se que as unhas das mãos estão espessas, opacas e com coloração amarelada. Qual a tríade diagnóstica?", "options": {"a": "Doença de Whipple.", "b": "Síndrome de Meigs.", "c": "Linfangioleiomiomatose (LAM).", "d": "Síndrome das Unhas Amarelas.", "e": "Hipotireoidismo severo (Mixedema)."}, "answer": "d", "rationale": "A Síndrome das Unhas Amarelas (Yellow Nail Syndrome) é uma condição rara caracterizada por: 1) Unhas amareladas e distróficas; 2) Linfedema; e 3) Derrame pleural exsudativo (geralmente linfocítico devido à disfunção linfática). A ascite também pode ocorrer como parte da linfedema sistêmico.", "option_rationales": {"a": "Incorreta. Whipple causa diarreia, perda de peso e dor articular, podendo causar serosite, mas não unhas amarelas.", "b": "Incorreta. A Síndrome de Meigs é a associação de tumor de ovário benigno + ascite + derrame pleural.", "c": "Incorreta. A LAM ocorre em mulheres em idade fértil e causa pneumotórax e quilotórax, não a distrofia ungueal descrita.", "d": "Correta. A descrição das unhas combinada com linfedema e derrame é patognomônica.", "e": "Incorreta. O mixedema causa transudatos e não se associa a distrofia ungueal amarelada isolada."}, "difficulty": "dificil", "tags": ["Pneumologia", "Dermatologia", "Derrame Pleural", "Síndromes Raras"]}', 53, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de NT-proBNP no líquido pleural é útil na diferenciação entre transudatos e exsudatos em contextos ambíguos. No entanto, qual a faixa de valor de corte (cut-off) comumente aceita no líquido pleural para sugerir etiologia de insuficiência cardíaca?", "options": {"a": "> 1.500 pg/mL", "b": "> 500 pg/mL", "c": "> 200 pg/mL", "d": "> 100 pg/mL", "e": "> 10.000 pg/mL"}, "answer": "a", "rationale": "O valor de corte de 1.500 pg/mL para o NT-proBNP no líquido pleural tem alta sensibilidade e especificidade (próximas de 90%) para o diagnóstico de derrame decorrente de insuficiência cardíaca congestiva. Valores abaixo disso em líquidos ambíguos favorecem o diagnóstico de exsudato.", "option_rationales": {"a": "Correta. 1.500 pg/mL é o valor clássico de referência diagnóstica.", "b": "Incorreta. Abaixo do ponto de corte validado na literatura principal.", "c": "Incorreta. Valor baixo demais, não específico.", "d": "Incorreta. Valor de transudato cardíaco é significativamente mais alto.", "e": "Incorreta. Valor exageradamente alto, embora possível em IC grave, o corte é menor."}, "difficulty": "dificil", "tags": ["Pneumologia", "Biomarcadores", "ICC", "NT-proBNP"]}', 54, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A Glicose no líquido pleural é consumida por processos inflamatórios intensos e atividade metabólica de células malignas ou bactérias. No entanto, qual das seguintes situações apresenta, paradoxalmente, níveis de glicose no líquido pleural EQUIVALENTES aos níveis séricos, mesmo na presença de um exsudato volumoso?", "options": {"a": "Derrame Pleural por Mesotelioma Maligno.", "b": "Tuberculose Pleural clássica.", "c": "Empiema bacteriano organizado.", "d": "Derrame Pleural por Quilotórax (não complicado).", "e": "Artrite Reumatoide em fase aguda."}, "answer": "d", "rationale": "No quilotórax primário ou traumático (sem infecção associada), a barreira pleural não está inflamada a ponto de impedir o transporte de glicose, e não há consumo bacteriano ou tumoral excessivo. Assim, a glicose pleural costuma ser equivalente à sérica, o que ajuda a diferenciar de outros exsudatos linfocíticos inflamatórios como a TB ou Câncer.", "option_rationales": {"a": "Incorreta. Glicose frequentemente baixa no câncer avançado.", "b": "Incorreta. Glicose costuma estar reduzida (< 60).", "c": "Incorreta. Glicose é muito baixa (< 40).", "d": "Correta. O quilo puramente linfático não altera a cinética da glicose.", "e": "Incorreta. A AR é a causa de glicose mais baixa de todas."}, "difficulty": "dificil", "tags": ["Pneumologia", "Bioquímica", "Quilotórax", "Glicose Pleural"]}', 55, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em um paciente com Derrame Parapneumônico Complicado onde o dreno tubular não está esvaziando a coleção devido à presença de múltiplas loculações e septações finas, a próxima intervenção recomendada antes de se considerar cirurgia agressiva (decorticação) é:", "options": {"a": "Uso de corticoides sistêmicos (Prednisona) para diminuir a fibrose.", "b": "Instilação intrapleural de fibrinolíticos (ex: Estreptoquinase ou tPA/DNase).", "c": "Manter conduta expectante com antibiótico por mais 14 dias.", "d": "Realização de pleurodese imediata para ''selar'' as loculações.", "e": "Aumento do calibre do dreno de tórax para 36 French."}, "answer": "b", "rationale": "A terapia fibrinolítica intrapleural (frequentemente tPA associado à DNase) pode ajudar a ''quebrar'' as septações de fibrina, facilitando a drenagem e evitando a necessidade de intervenção cirúrgica (VATS ou toracotomia) em até 30-50% dos casos selecionados.", "option_rationales": {"a": "Incorreta. Corticoides não têm papel estabelecido no tratamento do empiema loculado agudo.", "b": "Correta. Fibrinolíticos são indicados para derrames loculados na fase fibrinopurulenta.", "c": "Incorreta. A loculação impede a cura apenas com antibiótico, levando à organização do empiema.", "d": "Incorreta. Pleurodese em infecção ativa é um erro grave.", "e": "Incorreta. Calibres maiores não atravessam as septações finas do líquido loculado."}, "difficulty": "dificil", "tags": ["Pneumologia", "Empiema", "Fibrinolíticos", "Manejo Terapêutico"]}', 56, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 30 anos apresenta quadro de dor abdominal, náuseas e vômitos, seguido de dispneia e derrame pleural à esquerda 24h após o quadro inicial. A dosagem de amilase pleural é de 1.100 U/L (Sérica 950 U/L). RX de abdome sem pneumoperitônio. Qual a interpretação mais provável?", "options": {"a": "Adenocarcinoma gástrico metastático.", "b": "Tuberculose Pleural.", "c": "Derrame pleural simpático secundário a Pancreatite Aguda.", "d": "Ruptura esofágica aguda.", "e": "Derrame por trauma de baço."}, "answer": "c", "rationale": "A elefvação da amilase pleural ocorre em cerca de 10% das pancreatites agudas. O derrame costuma ser à esquerda pelo contato do pâncreas com o diafragma esquerdo. Diferente da fístula pancreática crônica, a amilase aqui costuma subir em paralelo à sérica ou levemente acima dela.", "option_rationales": {"a": "Incorreta. Câncer gástrico eleva amilase raramente e não de forma tão aguda.", "b": "Incorreta. TB não cursa com amilase alta.", "c": "Correta. Associação clássica aguda.", "d": "Incorreta. Daria amilase salivar (isoforma salivar) muito mais alta e quadro clínico de mediastinite grave.", "e": "Incorreta. Trauma de baço dá hemotórax, não elevação de amilase."}, "difficulty": "media", "tags": ["Pneumologia", "Gastroenterologia", "Pancreatite Aguda", "Amilase"]}', 57, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o quilotórax, qual das seguintes manobras pode ajudar a visualizar a fístula do ducto torácico durante a cirurgia?", "options": {"a": "Hiperventilação mecânica com PEEP alto.", "b": "Ingestão pré-operatória de creme de leite ou azeite misturado com corante (ex: azul de metileno).", "c": "Injeção de contraste iodado endovenoso.", "d": "Manobra de Valsalva mantida pelo anestesista.", "e": "Uso de corticoides 24h antes."}, "answer": "b", "rationale": "Oferecer uma refeição rica em gorduras (creme de leite, sorvete) algumas horas antes da cirurgia aumenta a produção de linfa leitosa, facilitando a identificação do ponto de vazamento do ducto torácico no mediastino.", "option_rationales": {"a": "Incorreta. Ajuda a ver fístulas aéreas, não linfáticas.", "b": "Correta. Técnica clássica de auxílio cirúrgico.", "c": "Incorreta. O contraste circula no sangue, não no sistema linfático de forma imediata e visível.", "d": "Incorreta. Útil para ver escape aéreo.", "e": "Incorreta. Não auxilia na visualização."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Quilotórax", "Manejo Intraoperatório"]}', 58, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurodese Espontânea'' é um fenômeno que pode ocorrer após a inserção de um cateter pleural de demora (PleurX) em pacientes com derrame neoplásico recorrente. Sobre este fenômeno, assinale a alternativa correta.", "options": {"a": "Ocorre apenas se forem injetados agentes esclerosantes pelo cateter diariamente.", "b": "Impede a reexpansão pulmonar e causa dor intratável.", "c": "A sínfise pleural ocorre pelo contato crônico e inflamação induzida pelo cateter, permitindo sua posterior retirada em cerca de 50% dos casos.", "d": "Ocorre em 100% dos pacientes após 30 dias de uso do cateter.", "e": "É um sinal de mau prognóstico, indicando falha renal iminente."}, "answer": "c", "rationale": "Pacientes com cateter pleural de demora podem desenvolver pleurodese espontânea (autopleurodese) em cerca de 45-50% das vezes. A drenagem constante e a irritação mecânica do cateter favorecem a adesão das pleuras, permitindo retirar o dreno de forma definitiva após a cessação do débito.", "option_rationales": {"a": "Incorreta. Ocorre espontaneamente apenas com a drenagem.", "b": "Incorreta. Pelo contrário, o cateter permite a saída controlada do líquido e alívio da dor.", "c": "Correta. Vantagem principal do cateter de demora em relação à pleurodese química única.", "d": "Incorreta. Ocorre em aproximadamente metade dos pacientes.", "e": "Incorreta. É um desfecho positivo e desejado."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Cateter de Demora", "Pleurodese"]}', 59, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Mesotelioma Maligno por citologia ou biópsia, a imuno-histoquímica é fundamental. Quais marcadores são tipicamente POSITIVOS no mesotelioma e ajudam a excluí-lo de um Adenocarcinoma metastático?", "options": {"a": "Calretinina, WT1 e Citoqueratina 5/6.", "b": "TTF-1 e Napsina A.", "c": "CEA e Ber-EP4.", "d": "Proteína S100 e HMB-45.", "e": "CD20 e CD30."}, "answer": "a", "rationale": "A calretinina, o WT1 (Wilms Tumor 1) e a citoqueratina 5/6 são os marcadores mesoteliais clássicos. Se presentes, confirmam a origem mesotelial da célula. O CEA, Ber-EP4, TTF-1 e Napsina A são marcadores clássicos de epitélio pulmonar/adenocarcinoma (negativos no mesotelioma).", "option_rationales": {"a": "Correta. Painel imuno-histoquímico padrão para mesotelioma.", "b": "Incorreta. Positivos no câncer de pulmão primário.", "c": "Incorreta. Positivos no adenocarcinoma.", "d": "Incorreta. Marcadores de melanoma.", "e": "Incorreta. Marcadores de linfoma."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Mesotelioma", "Imuno-histoquímica"]}', 60, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Fascite Eosinofílica'' (Síndrome de Shulman) pode cursar com qual manifestação torácica em cerca de 10% dos casos?", "options": {"a": "Pneumotórax bilateral.", "b": "Nódulos pulmonares gigantes.", "c": "Fístula traqueoesofágica.", "d": "Derrame pleural exsudativo com alta eosinofilia.", "e": "Calcificação da traqueia."}, "answer": "d", "rationale": "A fascite eosinofílica é uma doença esclerodermiforme rara. O envolvimento sistêmico pode incluir derrames pleurais que refletem a marca da doença: a eosinofilia. É um diagnóstico diferencial importante em derrames eosinofílicos de causa sistêmica ignorada.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta.", "d": "Correta. Manifestação serosa rara mas descrita da doença.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Eosinofilia", "Fascite"]}', 61, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico apresenta derrame pleural à direita com citologia oncótica demonstrando adenocarcinoma de pulmão. É realizada pleurodese química com talco via dreno de tórax. Dez horas após o procedimento, o paciente desenvolve hipoxemia severa, infiltrado pulmonar bilateral difuso ao RX (SDRA) e instabilidade hemodinâmica. Qual a causa mais provável dessa complicação?", "options": {"a": "Pneumotórax hipertensivo oculto.", "b": "Infarto agudo do miocárdio tipo 2.", "c": "Embolia pulmonar por fragmentos de tumor.", "d": "Edema pulmonar de reexpansão (EPR).", "e": "Reação inflamatória sistêmica ao talco (Síndrome de Resposta Inflamatória Sistêmica)."}, "answer": "e", "rationale": "A instilação de talco na pleura pode, raramente, causar uma reação inflamatória severa levando à SDRA (Síndrome do Desconforto Respiratório Agudo). Isso está associado especialmente ao uso de ''talco não graduado'' (com partículas muito pequenas que entram na circulação sistêmica) ou doses elevadas.", "option_rationales": {"a": "Incorreta. O dreno de tórax está no lugar, o que torna o pneumotórax menos provável como causa primária de SDRA.", "b": "Incorreta. Embora possível em idosos, o quadro relatado é clássico de complicação do talco.", "c": "Incorreta. A embolia tumoral não costuma ser desencadeada pela pleurodese de forma tão aguda.", "d": "Incorreta. O edama de reexpansão ocorre logo após a drenagem volumosa, não 10h após a pleurodese.", "e": "Correta. É uma complicação rara e grave da pleurodese com talco."}, "difficulty": "dificil", "tags": ["Pneumologia", "Pleurodese", "Complicações", "Oncologia"]}', 62, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre a ''Linfadenite Tuberculosa'' (Escrófula) e sua relação com o derrame pleural, qual a afirmação correta?", "options": {"a": "Apenas o derrame pleural exige tratamento com RIPE.", "b": "Sempre ocorrem juntas.", "c": "São formas extrapulmonares de TB que podem coexistir, especialmente em crianças e pacientes imunossuprimidos, indicando disseminação linfogênica do bacilo.", "d": "A escrófula cura o derrame pleural.", "e": "O dreno de tórax deve ser colocado no pescoço."}, "answer": "c", "rationale": "Ambas são manifestações de TB extrapulmonar. A coexistência de linfonodomegalia mediastinal ou cervical com derrame pleural reforça a suspeita diagnóstica de TB em casos onde o líquido pleural é linfocítico.", "option_rationales": {"a": "Incorreta. Ambas exigem o mesmo esquema RIPE.", "b": "Incorreta. Frequentemente ocorrem isoladas.", "c": "Correta. Visão sistêmica da infecção tuberculosa.", "d": "Incorreta. Uma não cura a outra.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Infectologia", "Tuberculose", "Extrapulmonar"]}', 63, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre a análise citológica do líquido pleural, a presença de uma grande quantidade de células mesoteliais (> 5%) em um exsudato linfocítico fala FORTEMENTE CONTRA qual diagnóstico?", "options": {"a": "Derrame Pleural por Artrite Reumatoide.", "b": "Derrame Pleural por LES.", "c": "Derrame Pleural por Adenocarcinoma.", "d": "Derrame Pleural por Tuberculose.", "e": "Derrame Pleural por Mesotelioma."}, "answer": "d", "rationale": "A Tuberculose Pleural é conhecida por causar uma intensa reação fibrinosa que ''reveste'' a pleura, impedindo a descamação de células mesoteliais para o líquido pleural. Portanto, encontrar muitas células mesoteliais no líquido pleural torna o diagnóstico de TB pleural extremamente improvável.", "option_rationales": {"a": "Incorreta. Na AR a pleura pode estar espessada, mas não há essa exclusão clássica como na TB.", "b": "Incorreta. O Lúpus não inibe a descamação mesotelial da mesma forma que a TB.", "c": "Incorreta. Neoplasias podem cursar com células mesoteliais normais descamadas.", "d": "Correta. A ausência de células mesoteliais é um dado sugestivo (mas não patognomônico) de TB.", "e": "Incorreta. O mesotelioma, por definição, tem células mesoteliais (malignas)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose Pleural", "Citologia", "Mesoteliais"]}', 64, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Morte por empiema'' em pacientes idosos com pneumonia é muitas vezes acelerada por qual fator relacionado ao manejo do líquido pleural?", "options": {"a": "Uso de antibióticos de espectro muito amplo.", "b": "Drenagem excessivamente rápida de transudatos.", "c": "Atraso no reconhecimento e na drenagem de derrames parapneumônicos complicados.", "d": "Realização de fisioterapia motora precoce.", "e": "Suplementação de oxigênio em altos fluxos."}, "answer": "c", "rationale": "O atraso em identificar que um derrame de pneumonia tornou-se complicado (empiema) é uma causa maior de morbimortalidade. A formação de carapaças, sepse persistente e encarceramento pulmonar ocorrem rapidamente se a drenagem não for instituída oportunamente.", "option_rationales": {"a": "Incorreta. O erro costuma ser o espectro insuficiente.", "b": "Incorreta. Transudatos raramente causam morte se drenados rápido (risco apenas de edema de reexpansão).", "c": "Correta. Tempo é pleura na infecção.", "d": "Incorreta. Fisioterapia é benéfica.", "e": "Incorreta. Não é o fator de aceleração da morte por infecção pleural."}, "difficulty": "facil", "tags": ["Pneumologia", "Empiema", "Mortalidade", "Erros Médicos"]}', 65, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Encerrando o estudo dos derrames pleurais: Qual é o ''sinal radiográfico'' que indica a presença de um grande volume de líquido pleural em uma radiografia de tórax realizada em DECÚBITO DORSAL (paciente deitado na UTI)?", "options": {"a": "Desaparecimento do coração.", "b": "Presença de bolhas de sabão.", "c": "Velamento difuso (Haze) de um hemitórax, com preservação da visualização dos vasos pulmonares através da ''névoa'' e ausência de desvio de estruturas mediastinais.", "d": "Nível hidroaéreo retilíneo.", "e": "Parábola de Damoiseau."}, "answer": "c", "rationale": "No paciente deitado, o líquido se espalha uniformemente por toda a superfície posterior do pulmão. O resultado é um aumento da densidade global (um ''véu'' branco) sobre o hemitórax acometido, diferente dos níveis localizados do paciente em pé.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Interpretação radiológica crítica no paciente crítico acamado.", "d": "Incorreta. Indica hidropneumotórax.", "e": "Incorreta. Sinal do derrame livre no paciente em ortostatismo."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "UTI", "Semiologia Radiológica"]}', 66, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Na abordagem do derrame parapneumônico loculado, o uso de fibrinolíticos intrapleurais (ex: tPA associado à DNase) demonstrou quais benefícios de acordo com o estudo MIST-2?", "options": {"a": "Redução da mortalidade em 50%.", "b": "Substituição completa do uso de antibióticos venosos.", "c": "Cura de derrames por Tuberculose de forma acelerada.", "d": "Aumento do risco de sangramento sem qualquer benefício terapêutico.", "e": "Melhora da drenagem radiológica e redução da necessidade de cirurgia invasiva, mas sem impacto provado na mortalidade."}, "answer": "e", "rationale": "O ensaio MIST-2 mostrou que a combinação de tPA (para quebrar a fibrina) e DNase (para reduzir a viscosidade do pus por lise de DNA de neutrófilos) melhora significativamente a drenagem e reduz a indicação de cirurgia (VATS/Decorticação) em pacientes com derrames parapneumônicos multiloculados.", "option_rationales": {"a": "Incorreta. Nenhum estudo provou redução de mortalidade absoluta direta apenas pelo fibrinolítico isolado.", "b": "Incorreta. Antibióticos são obrigatórios.", "c": "Incorreta. Fibrinolíticos não têm papel na TB pleural isolada.", "d": "Incorreta. Há risco de sangramento, mas o benefício em casos selecionados supera o risco.", "e": "Correta. Melhora do desfecho secundário de evitar cirurgia agressiva."}, "difficulty": "dificil", "tags": ["Pneumologia", "Evidência", "Empiema", "Fibrinolíticos"]}', 67, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente desenvolve derrame pleural volumoso. A toracentese revela líquido purulento com forte odor fétido. No Gram, observam-se múltiplas formas bacterianas (cocos e bastonetes), mas as culturas aeróbias tradicionais são negativas após 48h. Qual a provável etiologia?", "options": {"a": "Nocardose pleural.", "b": "Infecção por micro-organismos anaeróbios.", "c": "Líquido estéril pós-antibioticoterapia errática.", "d": "Hifas fúngicas mimetizando bactérias.", "e": "Tuberculose Pleural mucoide."}, "answer": "b", "rationale": "O odor fétido (putrefato) do líquido pleural é virtualmente patognomônico de infecção por bactérias anaeróbias. Como esses micro-organismos são de difícil crescimento em meios aeróbios ou ambientes sem transporte adequado, é comum que a cultura venha negativa se não houver meios específicos para anaeróbios.", "option_rationales": {"a": "Incorreta. Nocardia é aeróbia e não produz o odor característico de digestão de tecidos dos anaeróbios.", "b": "Correta. Característica clássica do empiema por anaeróbios (frequentemente secundário a aspiração).", "c": "Incorreta. Embora culturas negativas ocorram pós-atb, o odor aponta para a etiologia.", "d": "Incorreta. Fungos raramente produzem esse tipo de odor no espaço pleural.", "e": "Incorreta. TB não tem odor fétido."}, "difficulty": "media", "tags": ["Pneumologia", "Infectologia", "Anaeróbios", "Empiema"]}', 68, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente de 65 anos, portador de artrite reumatoide há 20 anos, apresenta derrame pleural bilateral de longa data, assintomático. Durante análise do líquido pleural, observa-se a presença de cristais rômbicos no sedimento sob luz polarizada. Este achado é sugestivo de:", "options": {"a": "Gota com acometimento pleural.", "b": "Artrite reumatoide em fase de remissão completa.", "c": "Contaminação do líquido por talco de luva.", "d": "Derrame Pleural por Colesterol (Pseudochylothorax).", "e": "Infecção por fungos filamentosos."}, "answer": "d", "rationale": "O pseudoquilotórax (ou derrame de colesterol) ocorre em derrames pleurais crônicos e espessados (frequentemente causados por AR ou Tuberculose de longa data). O colesterol se acumula no líquido, podendo formar cristais de colesterol típicos no sedimento. O TG costuma ser baixo (< 110 mg/dL), diferenciando do quilotórax verdadeiro.", "option_rationales": {"a": "Incorreta. Gota pleuropulmonar é extremamente rara; os cristais seriam de urato de sódio (agulhas).", "b": "Incorreta. O achado indica cronicidade e espessamento da pleura, não remissão da inflamação local.", "c": "Incorreta. Talco de luva tem aspecto de ''cruz de malta'' na luz polarizada.", "d": "Correta. Os cristais de colesterol são típicos de processos pleurais crônicos (Pseudochylothorax).", "e": "Incorreta. Fungos mostram hifas, não cristais rômbicos."}, "difficulty": "dificil", "tags": ["Pneumologia", "Bioquímica", "Colesterol Pleural", "Pseudoquilotórax"]}', 69, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de ''Pneumoempiema'' (ar e pus no espaço pleural) sem intervenção médica prévia (toracentese/drenagem) é indicativa de:", "options": {"a": "Infecção por vírus sincicial respiratório.", "b": "Bronquite crônica.", "c": "Fístula Broncopleural ou ruptura de abscesso pulmonar para a pleura.", "d": "Asma brônquica grave.", "e": "Simples efeito da gravidade."}, "answer": "c", "rationale": "A presença de gás no espaço pleural (hidropneumotórax) na ausência de trauma ou iatrogenia indica que há uma comunicação entre a via aérea (pulmão) e a pleura (fístula), ou que o micro-organismo causador da infecção é produtor de gás (ex: Clostridium ou algumas enterobactérias).", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Complicação mecânica de pneumonia/abscesso cavitado.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Empiema", "Fístula"]}', 70, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição do LDH pleural é fundamental nos critérios de Light. Em qual situação a dosagem de isoenzimas do LDH (LDH-1 a LDH-5) pode ter utilidade clínica?", "options": {"a": "Somente em exames veterinários.", "b": "Para diferenciar derrame neoplásico de empiema (LDH-4 e LDH-5 elevados no empiema/processos agudos).", "c": "Identificar quilotórax traumático.", "d": "Para confirmar Tuberculose Pleural.", "e": "Em derrames transudativos para prever resposta a diuréticos."}, "answer": "b", "rationale": "Embora raramente usadas, as isoenzimas do LDH refletem a origem da agressão tecidual. LDH-4 e LDH-5 (típicos de granulócitos) estão muito elevados em empiemas e processos inflamatórios agudos. No câncer, o padrão de isoenzimas costuma ser mais difuso ou com predomínio de LDH-2 e LDH-3.", "option_rationales": {"a": "Incorreta. Afirmação sem fundamento.", "b": "Correta. Ajuda a distinguir a fonte da inflamação celular no líquido.", "c": "Incorreta. Quilotórax tem LDH baixo.", "d": "Incorreta. Não tem valor específico na TB.", "e": "Incorreta. Transudatos têm LDH baixo, sem valor nas isoenzimas."}, "difficulty": "dificil", "tags": ["Pneumologia", "Laboratório", "Bioquímica", "LDH"]}', 71, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 55 anos apresenta derrame pleural volumoso recorrente. Estuda-se a realização de pleurodese química. Qual a importância de se medir o pH pleural e o grau de reexpansão pulmonar ANTES de realizar o procedimento?", "options": {"a": "Pulmão encarcerado é a indicação absoluta de talco insuflado (poudrage).", "b": "Apenas a idade do paciente importa.", "c": "pH < 7,10 e falha na reexpansão (pulmão encarcerado) predizem alto risco de falha da pleurodese.", "d": "Não têm importância, a pleurodese deve ser feita em todos.", "e": "Se o pH for normal, a pleurodese é contraindicada."}, "answer": "c", "rationale": "A pleurodese exige o contato entre as duas pleuras após a drenagem para que o processo inflamatório leve à sínfise. Se o pulmão estiver encarcerado (não expande), as pleuras não se tocam e o procedimento falha. Além disso, derrames com pH muito baixo em oncologia costumam refletir grande carga tumoral e pleura espessada, o que também diminui a chance de sucesso da pleurodese química.", "option_rationales": {"a": "Incorreta. Poudrage também exige contato pleural para funcionar.", "b": "Incorreta. Status funcional e expansibilidade são os critérios chave.", "c": "Correta. São os dois principais preditores de sucesso/falha do procedimento.", "d": "Incorreta. Taxa de falha pode ser alta em casos mal selecionados.", "e": "Incorreta. pH normal é favorável à pleurodese."}, "difficulty": "media", "tags": ["Pneumologia", "Terapêutica", "Pleurodese", "Pulmão Encarcerado"]}', 72, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico apresenta derrame pleural à direita. A análise mostra: pH 7,38, Glicose 105, Proteína 3,6 (Sérica 6,2), LDH 400 (Sérico 350). Citologia oncótica: células malignas compatíveis com adenocarcinoma de pulmão. É solicitada a pesquisa de mutações driver no líquido. Qual é a vantagem de se utilizar o ''bloco de células'' (cell block) em vez da citometria de fluxo ou esfregaço isolado?", "options": {"a": "Apenas o cell block consegue detectar bactérias.", "b": "Não há vantagem, sendo o esfregaço superior em todos os casos.", "c": "O cell block permite a análise da arquitetura tecidual e a realização de múltiplas colorações imuno-histoquímicas em cortes seriados.", "d": "O cell block evita a necessidade de centrífuga.", "e": "O cell block é mais rápido, ficando pronto em 15 minutos."}, "answer": "c", "rationale": "O ''Cell Block'' processa as células do líquido pleural como se fossem um fragmento de tecido de biópsia. Isso permite ao patologista realizar cortes seriados no bloco de parafina e aplicar um painel extenso de imuno-histoquímica (necessário para diferenciar mesotelioma de adenocarcinoma e identificar o sítio primário), além de disponibilizar material para testes moleculares (EGFR, ALK, PD-L1).", "option_rationales": {"a": "Incorreta. Bactérias podem ser vistas em qualquer método citológico se a carga for alta, embora o Gram/Cultura sejam os métodos de escolha.", "b": "Incorreta. O esfregaço é bom para morfologia individual, mas limitado para painéis imuno-histoquímicos complexos.", "c": "Correta. Razão principal para o processamento de cell block em oncologia pleural.", "d": "Incorreta. A centrífuga é necessária para concentrar as células para o bloco.", "e": "Incorreta. O processamento em parafina leva horas a dias."}, "difficulty": "media", "tags": ["Pneumologia", "Patologia", "Oncologia", "Cell Block"]}', 73, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual dos seguintes exames de imagem é o mais sensível para detectar pequenas quantidades de líquido pleural (em torno de 5 a 10 mL)?", "options": {"a": "Ressonância Magnética torácica.", "b": "Radiografia de tórax em decúbito lateral (Laurell).", "c": "Radiografia de tórax em perfil.", "d": "Ultrassonografia de tórax.", "e": "Radiografia de tórax em PA."}, "answer": "d", "rationale": "A ultrassonografia de tórax é extremamente sensível, conseguindo detectar volumes mínimos de 5-20 mL de líquido pleural. Para comparação, o RX em perfil precisa de cerca de 75 mL e o RX em PA de pelo menos 175-200 mL para apagar o seio costofrênico.", "option_rationales": {"a": "Incorreta. Cara e pouco prática para esta finalidade, apesar de detectar o líquido.", "b": "Incorreta. Detecta volumes a partir de 25-50 mL, mas menos sensível que o US.", "c": "Incorreta. Melhor que PA, mas ainda exige volume moderado.", "d": "Correta. Padrão-ouro para detecção de pequenos volumes e loculações.", "e": "Incorreta. Pouco sensível para volumes pequenos."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "Ultrassonografia", "Propedêutica"]}', 74, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Eosinofílica'' (Eosinófilos > 10%) torna qual diagnóstico EXTREMAMENTE IMPROVÁVEL?", "options": {"a": "Câncer de pulmão.", "b": "Tuberculose Pleural e TEP.", "c": "Linfoma.", "d": "Tuberculose Pleural (apenas).", "e": "Reação a drogas."}, "answer": "d", "rationale": "Embora existam exceções raras, encontrar eosinofilia importante no líquido pleural fala fortemente contra o diagnóstico de Tuberculose Pleural. Essa ''regra prática'' ajuda a priorizar outros exsudatos linfocíticos na ausência de eosinofilia.", "option_rationales": {"a": "Incorreta. Câncer pode dar eosinófilos.", "b": "Incorreta. TEP frequentemente cursa com eosinofilia pleural.", "c": "Incorreta. Alguns linfomas (T) podem dar eosinófilos.", "d": "Correta. Regra propedêutica clássica de exclusão (ou baixíssima probabilidade) de TB.", "e": "Incorreta. Drogas são causas comuns de eosinofilia."}, "difficulty": "media", "tags": ["Pneumologia", "Laboratório", "Derrame Eosinofílico", "Exclusão TB"]}', 75, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A presença de ''corpos psamomatosos'' (psammoma bodies) no estudo citológico do líquido pleural é um achado sugestivo de quais tipos de câncer primário?", "options": {"a": "Linfoma de Burkitt.", "b": "Adenocarcinoma de ovário, de tireoide ou mesotelioma.", "c": "Leucemia mieloide.", "d": "Carcinoma de pulmão de grandes células.", "e": "Câncer de próstata."}, "answer": "b", "rationale": "Os corpos psamomatosos são calcificações concêntricas microscópicas. Embora clássicos no carcinoma papilífero da tireoide e no seroso de ovário, também podem ser encontrados em mesoteliomas pleurais e adenocarcinomas de pulmão, sendo um forte indício de neoplasia epitelial papilar.", "option_rationales": {"a": "Incorreta. Linfomas não apresentam esses corpúsculos.", "b": "Correta. Achado citopatológico de valor diagnóstico.", "c": "Incorreta. Neoplasias hematológicas não formam calcificações psamomatosas.", "d": "Incorreta. Menos comum.", "e": "Incorreta. Não é o padrão."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Citopatologia", "Corpos Psamomatosos"]}', 76, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em um paciente com Derrame Pleural Maligno por Adenocarcinoma de Pulmão, qual mutação driver, se presente no tecido ou no bloco de células do líquido pleural, permite o uso de terapia-alvo oral com alta taxa de controle do derrame?", "options": {"a": "P53 mutação nula.", "b": "KRAS G12C.", "c": "HER2/neu amplificação.", "d": "EGFR (Exon 19 deletion ou L858R).", "e": "BRAF V600E."}, "answer": "d", "rationale": "A presença de mutações ativadoras do EGFR permite o tratamento com inibidores de tirosina quinase (ex: Osimertinibe). Esses pacientes costumam responder muito bem, com rápida involução do derrame pleural maligno na maioria das vezes, por vezes evitando pleurodeses.", "option_rationales": {"a": "Incorreta. Mutação supressora tumoral sem terapia-alvo específica de controle rápido de derrame.", "b": "Incorreta. Menos responsiva a terapias isoladas de controle de serosite.", "c": "Incorreta. Raro como driver isolado no pulmão.", "d": "Correta. Alvo clássico e muito eficaz em oncologia pulmonar.", "e": "Incorreta. Mais rara no pulmão e menos associada a remissão completa de serosite volumosa."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Terapia-Alvo", "EGFR"]}', 77, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o derrame pleural neutrofílico (predomínio de polimorfonucleares > 50%), qual das seguintes afirmações sobre o raciocínio diagnóstico está correta?", "options": {"a": "Descarta a possibilidade de neoplasia maligna primária.", "b": "É característico da fase crônica da Tuberculose Pleural.", "c": "Indica obrigatoriamente que o líquido é um transudato.", "d": "Sempre indica a necessidade de drenagem pleural por tubo.", "e": "Sugere processos agudos na pleura, como pneumonia, embolia pulmonar ou fase muito inicial da tuberculose."}, "answer": "e", "rationale": "A neutrofilia pleural é um sinal de inflamação aguda. As causas mais comuns são o derrame parapneumônico e a embolia pulmonar. Na tuberculose, os polimorfonucleares aparecem apenas nas primeiras 12-48 horas, sendo rapidamente substituídos por linfócitos.", "option_rationales": {"a": "Incorreta. Algumas neoplasias agressivas ou com infecção secundária podem cursar com neutrófilos.", "b": "Incorreta. A TB crônica é linfocítica.", "c": "Incorreta. Neutrofilia é típica de exsudatos.", "d": "Incorreta. O derrame parapneumônico simples não exige drenagem, apenas o antibiótico.", "e": "Correta. Reflete o estágio inflamatório agudo da pleura."}, "difficulty": "dificil", "tags": ["Pneumologia", "Bioquímica Líquido Pleural", "Diagnóstico Diferencial"]}', 78, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente feminina, 28 anos, apresenta quadro de tosse seca e dor pleurítica à direita há 15 dias, acompanhada de febre baixa vespertina. O RX de tórax mostra derrame pleural ocupando um terço do hemitórax direito. A análise do líquido pleural revela: Predomínio de linfócitos (85%), glicose de 72 mg/dL, ADA (Adenosina deaminase) de 65 U/L. Não foram visualizados germes no Gram ou BAAR no sedimento. Assinale a alternativa que apresenta o diagnóstico mais provável e o próximo passo recomendado.", "options": {"a": "Pneumonia bacteriana atípica; iniciar claritromicina e repetir RX em 48 horas.", "b": "Lúpus Eritematoso Sistêmico; dosar anticorpos antinucleares (FAN) no líquido pleural.", "c": "Tuberculose pleural; iniciar esquema RIPE conforme diretrizes nacionais.", "d": "Mesotelioma maligno; solicitar citologia oncótica e marcadores imuno-histoquímicos.", "e": "Derrame parapneumônico simples; realizar nova toracentese para drenagem de alívio."}, "answer": "c", "rationale": "Em áreas endêmicas como o Brasil, um líquido pleural exsudativo com predomínio linfocítico e ADA elevado (> 40-60 U/L) tem altíssimo valor preditivo positivo para Tuberculose Pleural, especialmente em pacientes jovens com sintomas subagudos. O diagnóstico pode ser presumido com base nesses achados, permitindo o início do tratamento (esquema RIPE).", "option_rationales": {"a": "Incorreta. Pneumonias atípicas raramente causam derrames com esse perfil citológico e bioquímico.", "b": "Incorreta. O LES costuma apresentar ADA mais baixo e outros sintomas sistêmicos (artralgia, rash).", "c": "Correta. O binômio linfocitose + ADA alto é fortemente sugestivo de TB pleural no Brasil.", "d": "Incorreta. Muito improvável pela idade da paciente e pelo valor de ADA.", "e": "Incorreta. O perfil do líquido (linfocítico) afasta o diagnóstico de exsudato neutrofílico parapneumônico."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural", "Tuberculose", "ADA"]}', 79, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico e etilista é diagnosticado com câncer de esôfago médio. Ele desenvolve derrame pleural volumoso à direita, de aspecto purulento, com pH 6,8. No líquido, observa-se a presença de partículas de alimentos e amilase pleural de 15.000 U/L. Qual a conduta cirúrgica MAIS URGENTE?", "options": {"a": "Esofagectomia de emergência ou exclusão esofágica com drenagem mediastinal e pleural ampla.", "b": "Gastrostomia para alimentação.", "c": "Mediastinostomia cervical para drenagem de abscesso.", "d": "Drenagem pleural tubular e antibioticoterapia venosa apenas.", "e": "Toracocinese de alívio seguida de endoscopia digestiva diagnóstica."}, "answer": "a", "rationale": "A presença de partículas de alimento no líquido pleural confirma ruptura esofágica (Síndrome de Boerhaave ou perfuração neoplásica). Trata-se de uma emergência cirúrgica catastrófica com mediastinite química e bacteriana severa. O tratamento exige controle imediato da fístula e drenagem agressiva de todos os compartimentos contaminados.", "option_rationales": {"a": "Correta. Conduta de salvação para ruptura esofágica com contaminação pleural.", "b": "Incorreta. Medida de suporte que não resolve a infecção pleural/mediastinal ativa.", "c": "Incorreta. A perfuração é torácica (esôfago médio), a mediastinostomia cervical não alcança o foco adequadamente.", "d": "Incorreta. Insuficiente diante de uma fístula digestiva contínua.", "e": "Incorreta. Procedimento diagnóstico puramente, a urgência é terapêutica."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Esofagostomia", "Mediastinite"]}', 80, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição do ''tempo de protrombina'' (TAP/INR) e ''tempo de tromboplastina parcial ativada'' (TTPA) no Líquido Pleural é recomendada?", "options": {"a": "Sim, para avaliar risco de sangramento local.", "b": "Sim, substitui a coleta de sangue periférico.", "c": "Apenas se o paciente usar Varfarina.", "d": "Mandatório no empiema.", "e": "Não, pois o líquido pleural é naturalmente deficiente em fatores de coagulação e os valores não têm correlação com o risco de sangramento clínico ou status sistêmico."}, "answer": "e", "rationale": "Os testes de coagulação são padronizados para o plasma. O líquido pleural (especialmente após desfibrinação no hemotórax) não possui os mesmos níveis de proteínas da cascata, tornando a dosagem desses tempos no líquido inúteis e tecnicamente inválidas.", "option_rationales": {"a": "Incorreta. O risco é avaliado no sangue periférico.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Correta. Inutilidade clínica do teste no compartimento pleural."}, "difficulty": "media", "tags": ["Pneumologia", "Laboratório", "Bioquímica", "Coagulação"]}', 81, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o Mesotelioma Maligno em relação ao tabagismo, assinale a alternativa correta.", "options": {"a": "O tabagismo é o principal fator de risco para mesotelioma, superando o asbesto.", "b": "Apenas o tabagismo passivo é fator de risco para mesotelioma.", "c": "O tabagismo não tem relação causal com o mesotelioma; o risco é determinado quase exclusivamente pela exposição ao asbesto.", "d": "O tabagismo e o asbesto agem de forma sinérgica (multiplicativa) no risco de mesotelioma, assim como no câncer de pulmão.", "e": "Fumar protege contra o mesotelioma devido à indução de muco protetor."}, "answer": "c", "rationale": "Diferentemente do câncer de pulmão (carcinoma), onde tabaco e asbesto multiplicam o risco, o mesotelioma pleural não tem associação direta com o fumo. O fator determinante é a inalação de fibras de amianto (asbesto) e, em menor escala, radiação ou erionita.", "option_rationales": {"a": "Incorreta. O fumo causa adenocarcinoma e epidermoide, não mesotelioma.", "b": "Incorreta. Sem nexo causal estabelecido.", "c": "Correta. Dado importante de epidemiologia para diferenciar das outras neoplasias torácicas.", "d": "Incorreta. A sinergia ocorre apenas para o câncer de pulmão ''comum'', não para o mesotelioma.", "e": "Incorreta. Afirmativa estapafúrdia."}, "difficulty": "media", "tags": ["Pneumologia", "Epidemiologia", "Mesotelioma", "Tabagismo"]}', 82, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal indicação para a realização de angiografia por tomografia (Angio-TC) em um paciente com hemotórax traumático drenado que persiste com drenagem > 200 mL/hora por 3 horas consecutivas?", "options": {"a": "Apenas por rotina administrativa.", "b": "Verificar se o dreno é de boa marca.", "c": "Identificar sangramento ativo de vasos da parede (ex: artéria intercostal ou mamária interna) para possível embolização ou planejamento cirúrgico.", "d": "Diagnosticar pneumonia associada.", "e": "Rastrear embolia pulmonar simultânea."}, "answer": "c", "rationale": "Drenagem persistente e volumosa (> 200 mL/h) indica sangramento arterial ativo. A Angio-TC ou a arteriografia ajudam a localizar o vaso sangrante antes da toracotomia de emergência ou para permitir a embolização por radiologia intervencionista em casos selecionados.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Indicação de imagem para urgência vascular torácica.", "d": "Incorreta.", "e": "Incorreta. TEP não causa hemotórax maciço de 200mL/h."}, "difficulty": "facil", "tags": ["Pneumologia", "Cirurgia de Trauma", "Hemotórax", "Diagnóstico"]}', 83, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente em uso crônico de Amiodarona para tratamento de arritmia desenvolve derrame pleural bilateral e infiltrado pulmonar reticular fino. A biópsia pulmonar e pleural revela a presença de macrófagos com citoplasma ''espumoso'' (foam cells). Este achado é:", "options": {"a": "Característico de edema agudo de pulmão por falha do ventrículo esquerdo.", "b": "Sinal patognomônico de toxicidade pulmonar pela Amiodarona.", "c": "Indicação imediata de quimioterapia para linfoma.", "d": "Sinal de exposição à droga, mas não necessariamente de toxicidade estabelecida (pode ocorrer em pacientes assintomáticos que usam a medicação).", "e": "Sinal de infecção por Pneumocystis jirovecii."}, "answer": "d", "rationale": "A presença de ''foam cells'' (macrófagos com lamelas fosfolipídicas por inibição da fosfolipase pela droga) indica que o paciente está impregnado pela Amiodarona, mas não confirma que a inflamação e o derrame sejam causados exclusivamente pela toxicidade. O diagnóstico de toxicidade pulmonar é de exclusão, baseando-se no quadro clínico, radiológico e resposta à suspensão da droga.", "option_rationales": {"a": "Incorreta. Congestão causa macrófagos com hemossiderina (Heart failure cells).", "b": "Incorreta. Muitos usuários da droga têm essas células sem ter doença pulmonar ativa.", "c": "Incorreta. Não indica malignidade.", "d": "Correta. Distinção importante de patologia: exposição vs doença.", "e": "Incorreta. Pneumocystis apresenta exsudato espumoso ''intra-alveolar'' característico, mas as ''foam cells'' de macrófagos são clássicas da Amiodarona."}, "difficulty": "dificil", "tags": ["Pneumologia", "Farmacodinâmica", "Amiodarona", "Efeitos Colaterais"]}', 84, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal causa de morte imediata por acidente punção durante uma toracocentese diagnóstica realizada por via posterior?", "options": {"a": "Edema agudo de pulmão.", "b": "Pneumotórax bilateral.", "c": "Lesão do fígado ou baço (hemoperitônio maciço por punção transdiafragmática).", "d": "Laceração da aorta descendente.", "e": "Choque vagal."}, "answer": "c", "rationale": "Punções muito baixas (abaixo do 9º espaço intercostal) ou sem guia de ultrassom podem levar à passagem da agulha pelo diafragma e lesão de órgãos sólidos abdominais (baço à esquerda, fígado à direita). O hemoperitônio resultante pode ser volumoso e levar ao choque antes mesmo que o médico perceba o erro intra-abdominal no procedimento torácico.", "option_rationales": {"a": "Incorreta. Complicação tardia de drenagem volumosa, não do acidente de punção imediato.", "b": "Incorreta. Raro agulha puncionar os dois lados simultaneamente.", "c": "Correta. Acidente anatômico grave potencial.", "d": "Incorreta. A aorta é medial e o trajeto da punção costuma ser lateral/linha axilar.", "e": "Incorreta. Grave, mas raramente letal com manobras simples."}, "difficulty": "media", "tags": ["Pneumologia", "Procedimentos", "Anatomia", "Complicações"]}', 85, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A presença de infiltrados pulmonares migratórios e derrame pleural com eosinofilia intensa (> 20%) em um paciente com asma grave recém-diagnosticada sugere qual vasculite sistêmica?", "options": {"a": "Granulomatose de Wegener.", "b": "Arterite de Células Gigantes.", "c": "Doença de Behçet.", "d": "Poliarterite Nodosa.", "e": "Granulomatose Eosinofílica com Poliangiite (Churg-Strauss)."}, "answer": "e", "rationale": "A síndrome de Churg-Strauss é definida pela tríade: asma, eosinofilia periférica/tecidual e vasculite sistêmica. O derrame pleural exsudativo eosinofílico ocorre em cerca de 30% dos pacientes durante a fase de vasculite ativa.", "option_rationales": {"a": "Incorreta. Cursa com nódulos cavitados e granulomas, não eosinofilia marcada.", "b": "Incorreta. Vasculite de grandes vasos em idosos.", "c": "Incorreta. Afta oral, genital e uveíte; acometimento pleural é raro.", "d": "Incorreta. Não acomete o pulmão de forma clássica.", "e": "Correta. Tríade clínica clássica."}, "difficulty": "facil", "tags": ["Pneumologia", "Vasculites", "Churg-Strauss", "Asma"]}', 86, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No manejo do Quilotórax Refratário ao tratamento conservador (dieta com TCM, octreotide), em um paciente com insuficiência cardíaca grave ou cirrose, uma opção de tratamento avançado que reduz a pressão no sistema linfático através da descompressão biliar/portal é:", "options": {"a": "Transplante de pulmão.", "b": "Criação de fístula arteriovenosa no braço.", "c": "Pleurectomia parietal radical.", "d": "TIPS (Shunt Portossistêmico Intra-hepático Transjugular).", "e": "Ligadura do ducto torácico via cervical."}, "answer": "d", "rationale": "Em casos de quilotórax ou hidrotórax hepático secundários à hipertensão portal ou pressões venosas centrais elevadas, o TIPS pode reduzir a produção de linfa e favorecer a resolução do derrame por melhorar a dinâmica hemodinâmica sistêmica e esplâncnica.", "option_rationales": {"a": "Incorreta. Conduta extrema não indicada para quilotórax isolado.", "b": "Incorreta. Aumentaria a sobrecarga cardíaca.", "c": "Incorreta. Procedimento de alto risco em pacientes com IC/Cirrose.", "d": "Correta. Opção terapêutica para casos cirrogênicos/hemodinâmicos refratários.", "e": "Incorreta. O ducto deve ser ligado no tórax, não na cervical, para a maioria dos derrames pleurais."}, "difficulty": "dificil", "tags": ["Pneumologia", "Gastroenterologia", "Terapêutica Avançada", "Quilotórax"]}', 87, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal indicação absoluta para a realização de biópsia pleural por agulha (como a agulha de Cope ou Abrams) em pacientes com derrame pleural exsudativo?", "options": {"a": "Derrame neoplásico já confirmado por citologia para estadiamento.", "b": "Suspeita de Tuberculose Pleural quandoADA é inconclusivo ou em locais de baixa incidência.", "c": "Derrame parapneumônico que não responde ao antibiótico inicial.", "d": "Avaliação de espessamento pleural no mesotelioma.", "e": "Derrame pleural hemorrágico pós-traumático."}, "answer": "b", "rationale": "A biópsia pleural por agulha tem sua maior utilidade na investigação de Tuberculose Pleural, onde o rendimento da análise histopatológica + cultura do fragmento é superior à citologia e cultura do líquido isoladamente. Para neoplasias, a VATS (biópsia dirigida) é preferível se a citologia for negativa.", "option_rationales": {"a": "Incorreta. Se a citologia já confirmou, a biópsia cega não acrescenta muito ao estadiamento.", "b": "Correta. A biópsia pleural é o exame de escolha para confirmar TB pleural (visualização do granuloma).", "c": "Incorreta. Biópsia não é indicada em processos infecciosos agudos piogênicos.", "d": "Incorreta. No mesotelioma, a biópsia cega tem baixo rendimento, sendo indicada a biópsia por videotoracoscopia.", "e": "Incorreta. O trauma exige drenagem ou VATS, não biópsia por agulha cega."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose Pleural", "Biópsia", "Procedimentos"]}', 88, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente gestante (30 semanas) apresenta dispneia intensa, edema de face e membros, associado a hipertensão arterial (170/110 mmHg). A radiografia de tórax revela derrame pleural bilateral e edema pulmonar. Qual a causa mais provável deste derrame pleural?", "options": {"a": "Síndrome de Meigs gestacional.", "b": "Preeclâmpsia com edema agudo de pulmão e anasarca.", "c": "Pneumonia comunitária grave.", "d": "Embolia amniótica.", "e": "Tuberculose reativada na gestação."}, "answer": "b", "rationale": "A preeclâmpsia grave causa disfunção endotelial sistêmica, aumento da permeabilidade capilar e queda da pressão oncótica (pela proteinúria). Isso resulta em derrames cavitários (pleural, ascite) e edema alveolar, sendo uma causa importante de insuficiência respiratória no terceiro trimestre.", "option_rationales": {"a": "Incorreta. Meigs é associado a tumores benignos de ovário, não à hipertensão gestacional.", "b": "Correta. Complicação obstétrica sistêmica clássica.", "c": "Incorreta. Menos comum que a preeclâmpsia no contexto de hipertensão aguda.", "d": "Incorreta. Quadro catastrófico de choque cardiogênico e CIVD súbita durante o trabalho de parto.", "e": "Incorreta. A TB não explica a hipertensão aguda e o edema generalizado súbito."}, "difficulty": "facil", "tags": ["Pneumologia", "Obstetrícia", "Preeclâmpsia", "Derrame na Gravidez"]}', 89, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 52 anos com Leucemia Mieloide Crônica (LMC) em tratamento com Dasatinibe há 6 meses apresenta-se com dispneia progressiva e tosse seca. A radiografia de tórax revela derrame pleural bilateral volumoso. A toracentese mostra um exsudato linfocítico com citologia oncótica negativa. Após exclusão de infecções e progressão da doença de base, qual a melhor conduta para este paciente?", "options": {"a": "Suspensão temporária do Dasatinibe e uso de diuréticos/corticoides conforme necessidade.", "b": "Encaminhar para decorticação pulmonar bilateral.", "c": "Realizar pleurodese imediata com talco.", "d": "Substituir Dasaribe por Hidroxiureia permanentemente.", "e": "Iniciar quimioterapia de resgate para progressão de LMC."}, "answer": "a", "rationale": "O Dasatinibe, um inibidor de tirosina quinase, é uma causa bem conhecida de derrame pleural (ocorre em até 20-30% dos pacientes). O líquido é classicamente um exsudato linfocítico. A conduta padrão envolve a pausa da medicação ou redução da dose, associada a diuréticos ou cursos curtos de corticoides. O derrame costuma recorrer se a droga for reiniciada na mesma dose.", "option_rationales": {"a": "Correta. Pausa da droga e suporte clínico é a conduta recomendada.", "b": "Incorreta. Medida invasiva desnecessária para um efeito colateral reversível.", "c": "Incorreta. Pleurodese não é tratamento para derrame induzido por droga antes de tentar o manejo medicamentoso.", "d": "Incorreta. A substituição pode ser necessária, mas o Dasatinibe é uma droga de ponta; tenta-se o ajuste de dose antes da troca definitiva se possível.", "e": "Incorreta. O derrame é um efeito colateral da droga, não sinal de falha terapêutica da LMC."}, "difficulty": "dificil", "tags": ["Pneumologia", "Hematologia", "Derrame Iatrogênico", "Dasatinibe"]}', 90, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico e com histórico de exposição ocupacional ao asbesto há 30 anos apresenta-se com dor torácica persistente e emagrecimento. A tomografia mostra espessamento pleural nodular e circunferencial envolvendo a pleura parietal e visceral, com invasão do diafragma e gordura mediastinal. O diagnóstico histopatológico revela Mesotelioma Maligno. Qual o subtipo histológico mais comum e de melhor prognóstico?", "options": {"a": "Pequenas Células.", "b": "Desmoplásico.", "c": "Bifásico.", "d": "Epitelioide.", "e": "Sarcomatoide."}, "answer": "d", "rationale": "O mesotelioma epitelioide é a variante histológica mais comum (50-70% dos casos) e apresenta um prognóstico significativamente melhor do que as variantes sarcomatoide ou bifásica. O diagnóstico imuno-histoquímico (Calretinina, WT1) é essencial para distinguir do adenocarcinoma.", "option_rationales": {"a": "Incorreta. Não é um subtipo clássico do mesotelioma pleural.", "b": "Incorreta. Variante rara e geralmente muito agressiva.", "c": "Incorreta. Combina elementos epitelioides e sarcomatoides, prognóstico intermediário.", "d": "Correta. Mais comum e com sobrevida ligeiramente superior.", "e": "Incorreta. Variante agressiva e de pior prognóstico."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Mesotelioma", "Asbesto"]}', 91, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente com derrame pleural por Tuberculose apresenta citologia com predomínio de linfócitos, mas baixa porcentagem de células NK (Natural Killer). Este achado correlaciona-se com:", "options": {"a": "Presença de vírus Influenza.", "b": "Inexistência de bacilos.", "c": "Mecanismo imunitário local focado em linfócitos T CD4 efetores, sendo o perfil TH1 (IFN-gama) o dominante na patogênese.", "d": "Indicação de transplante de medula.", "e": "Curatela rápida."}, "answer": "c", "rationale": "A TB pleural é o arquétipo da resposta imune celular TH1. A pleura fica repleta de linfócitos T CD4 que produzem interferon-gama, ativando macrófagos para formar granulomas. As células NK participam, mas o motor da inflamação é o linfócito T antígeno-específico.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Imunologia da serosite tuberculosa.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Imunologia", "Tuberculose", "Linfócitos"]}', 92, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal causa de morte por complicações do procedimento de toracentese de grande volume (> 1,5 L)?", "options": {"a": "Hemorragia por laceração da artéria intercostal.", "b": "Síncope vasovagal com parada em assistolia.", "c": "Pneumotórax hipertensivo.", "d": "Edema Pulmonar de Reexpansão (EPR).", "e": "Embolia gasosa coronariana."}, "answer": "d", "rationale": "O edema pulmonar de reexpansão é a complicação mais temida em toracocenteses ou drenagens volumosas. Ocorre por danos causados por radicais livres durante a reoxigenação rápida do pulmão previamente colapsado e mudanças bruscas na pressão hidrostática. Pode levar à falência respiratória grave e choque.", "option_rationales": {"a": "Incorreta. Grave, mas cirurgicamente controlável.", "b": "Incorreta. Frequentemente benigna se manejada com posição.", "c": "Incorreta. Grave, mas tratável com drenagem imediata.", "d": "Correta. Complicação sistêmica grave por agressão endotelial pós-reexpansão.", "e": "Incorreta. Rara e imediata ao acidente de punção."}, "difficulty": "media", "tags": ["Pneumologia", "Procedimentos", "EPR", "Complicações"]}', 93, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O escore RAPID foi validado para prever o prognóstico de pacientes com infecção pleural (Empiema/Derrame Parapneumônico). Quais são as variáveis que compõem este escore?", "options": {"a": "Radiologia, ADA, Proteína, Idade, Densidade.", "b": "Raciocínio, Albumina, pH, Idade, Derrame.", "c": "Renal (Ureia), Age (Idade), Purulence (Purulência do líquido), Infection source (Hospitalar vs Comunitária), Dietary (Estado Nutricional).", "d": "Respiração, Albumina, Plaqueta, Idade, Diabetes.", "e": "Renal (Ureia), Age (Idade), Purulence (Purulência), Infection source (Hospitalar vs Comunitária), Dietary (Albumina)."}, "answer": "e", "rationale": "O escore RAPID utiliza: Renal (Ureia sérica), Age (Idade), Purulence (se o líquido é purulento ou não), Infection source (Comunitária vs Nosocomial) e Dietary (Albumina sérica). Ele estratifica o risco de morte em 3 meses.", "option_rationales": {"a": "Incorreta. ADA e Densidade não compõem o escore.", "b": "Incorreta. Raciocínio não é variável clínica objetiva.", "c": "Incorreta. ''Dietary'' não é estado nutricional genérico, mas especificamente a Albumina.", "d": "Incorreta. Plaqueta e Diabetes não fazem parte do RAPID clássico.", "e": "Correta. Definição correta do acrônimo e das variáveis."}, "difficulty": "dificil", "tags": ["Pneumologia", "Infectologia", "Prognóstico", "Escore RAPID"]}', 94, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um homem de 58 anos, com diagnóstico prévio de Linfoma de Hodgkin em remissão após quimioterapia e radioterapia mediastinal há 5 anos, apresenta-se com dispneia aos esforços e tosse seca. A tomografia de tórax revela espessamento pleural difuso e derrame pleural loculado à direita. A análise do líquido pleural mostra exsudato linfocítico, com glicose de 45 mg/dL e LDH de 550 U/L. A citologia oncótica e a cultura são negativas. A biópsia pleural por videotoracoscopia revela fibrose densa com hialinização, sem sinais de malignidade. Qual a causa mais provável para este derrame?", "options": {"a": "Pleura ''encarcerada'' secundária à radioterapia (fibrose pleural actínica).", "b": "Mesotelioma maligno induzido por radioterapia prévia.", "c": "Derrame pleural por toxicidade tardia à bleomicina.", "d": "Pneumonite por radiação com extensão pleural tardia.", "e": "Recidiva do linfoma de Hodgkin na pleura."}, "answer": "a", "rationale": "A radioterapia mediastinal para o tratamento de linfomas pode causar fibrose pleural e pericárdica tardia, levando ao quadro de pulmão encarcerado ou derrames exsudativos puramente fibróticos (pleura actínica). O achado histopatológico de hialinização e fibrose densa sem células malignas, anos após o tratamento, é característico dessa condição.", "option_rationales": {"a": "Correta. A fibrose pleural actínica é uma complicação tardia bem descrita da radioterapia torácica.", "b": "Incorreta. Embora o mesotelioma possa ser induzido por radiação, o achado de fibrose hialina na biópsia aponta para uma causa benigna (cicatricial).", "c": "Incorreta. A toxicidade pela bleomicina geralmente se manifesta como fibrose pulmonar intersticial, não como derrame pleural isolado e espessamento hialino.", "d": "Incorreta. A pneumonite actínica costuma ocorrer nos primeiros meses após a radioterapia, não após 5 anos.", "e": "Incorreta. A biópsia negativa e o tempo de remissão tornam a recidiva menos provável que a complicação fibrótica."}, "difficulty": "dificil", "tags": ["Pneumologia", "Radioterapia", "Fibrose Pleural", "Derrame Pleural"]}', 95, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um recém-nascido submetido à cirurgia de correção de cardiopatia congênita desenvolve derrame pleural volumoso no 5º dia pós-operatório. O líquido tem aspecto leitoso, TG = 150 mg/dL e presença de quilomícrons na eletroforese. Sobre o manejo inicial do Quilotórax, assinale a alternativa correta.", "options": {"a": "Antibioticoterapia profilática visando estafilococos da pele.", "b": "Drenagem pleural e dieta rica em triglicerídeos de cadeia longa (TCL).", "c": "Pleurodese imediata com nitrato de prata para selar o ducto torácico.", "d": "Ligadura imediata do ducto torácico por toracotomia nas primeiras 24h.", "e": "Uso de octreotide e dieta com triglicerídeos de cadeia média (TCM) ou jejum/NPP."}, "answer": "e", "rationale": "O manejo inicial do quilotórax pós-operatório é conservador na maioria dos casos. Envolve a redução da produção de linfa através de dieta com TCM (que é absorvido diretamente pelo sistema porta, saltando o ducto torácico) ou jejum total com Nutrição Parenteral Prolongada (NPP). O octreotide pode ser usado para reduzir as secreções esplâncnicas.", "option_rationales": {"a": "Incorreta. O quilo é estéril e possui propriedades bacteriostáticas.", "b": "Incorreta. A dieta deve ser pobre em TCL, pois estes estimulam o fluxo linfático.", "c": "Incorreta. Pleurodese não é o tratamento inicial para quilotórax em crianças.", "d": "Incorreta. A cirurgia é reservada para casos que falham ao tratamento clínico após 1-2 semanas.", "e": "Correta. Dieta com TCM e octreotide são os pilares do tratamento clínico inicial."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cirurgia Torácica", "Quilotórax", "Pós-operatório"]}', 96, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Atualmente, qual é o calibre de dreno pleural recomendado para o manejo inicial da maioria dos empiemas e derrames parapneumônicos, visando o conforto do paciente sem prejuízo na eficácia da drenagem?", "options": {"a": "Drenos de grande calibre (28-36 French).", "b": "Apenas agulhas de biópsia 14G.", "c": "Toracotomia aberta sem dreno.", "d": "Drenos de fino calibre (8-14 French), conhecidos como ''Pigtails''.", "e": "Sondas nasogástricas adaptadas."}, "answer": "d", "rationale": "Estudos randomizados recentes demonstraram que drenos de fino calibre (Pigtails, inseridos pela técnica de Seldinger) são tão eficazes quanto os drenos calibrosos para o manejo do empiema, com a vantagem de serem muito menos dolorosos para o paciente e apresentarem menores taxas de complicações de inserção.", "option_rationales": {"a": "Incorreta. Padrão antigo, agora reservado para hemotórax traumático com coágulos.", "b": "Incorreta. Insuficiente para drenagem contínua.", "c": "Incorreta. Procedimento de exceção para empiemas crônicos graves.", "d": "Correta. Tendência moderna de ''less is more'' no empiema.", "e": "Incorreta. Gambiarra não recomendada por diretrizes."}, "difficulty": "media", "tags": ["Pneumologia", "Terapêutica", "Drenagem Pleural", "Dispositivos"]}', 97, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 35 anos, com histórico de trauma esplênico grave (esplenectomia traumática) há 10 anos, apresenta-se agora com múltiplos pequenos nódulos pleurais incidentais em uma tomografia de tórax de rotina. Os nódulos são periféricos, bem delimitados e captam contraste. O paciente é assintomático. Qual a principal hipótese diagnóstica que evitaria uma biópsia desnecessária?", "options": {"a": "Metástases de tumor primário desconhecido.", "b": "Sarcoidose nodular pleural.", "c": "Empiema crônico calcificado.", "d": "Mesotelioma maligno multicêntrico.", "e": "Esplenose Torácica."}, "answer": "e", "rationale": "A esplenose torácica ocorre quando fragmentos de tecido esplênico são ''semeados'' na pleura após um trauma tóraco-abdominal com ruptura diafragmática e esplênica simultâneas. O tecido cresce e se vasculariza como múltiplos nódulos pleurais funcionantes. O diagnóstico pode ser confirmado por cintilografia com hemácias marcadas com tecnécio-99m (Tc-99m) ou mapeamento esplênico.", "option_rationales": {"a": "Incorreta. No jovem assintomático com história de trauma prévio, a esplenose é mais provável.", "b": "Incorreta. Sarcoidose costuma ter linfonodomegalia hilar associada.", "c": "Incorreta. Nódulos de esplenose não são necessariamente calcificados.", "d": "Incorreta. O asbesto e o tempo de latência não batem com o quadro.", "e": "Correta. Diagnóstico diferencial importante para nódulos pleurais pós-trauma."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cirurgia de Trauma", "Esplenose Torácica", "Nódulo Pleural"]}', 98, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A exposição ocupacional ao asbesto (amianto) pode causar várias doenças pleurais benignas. Qual delas é caracterizada por ser unilateral, frequentemente recorrente, assintomática ou associada a dor leve, e que resolve espontaneamente deixando muitas vezes apenas o ângulo costofrênico rombo?", "options": {"a": "Mesotelioma Maligno em fase inicial.", "b": "Placas Pleurais Parietais.", "c": "Derrame Pleural Benigno do Asbesto (BAPE).", "d": "Asbestose Pulmonar.", "e": "Atelectasia Redonda."}, "answer": "c", "rationale": "O BAPE (Benign Asbestos Pleural Effusion) é a manifestação mais precoce da exposição ao asbesto (ocorre nos primeiros 10-20 anos). É um exsudato, muitas vezes hemorrágico ou eosinofílico, que costuma resolver sozinho entre 3 a 4 meses, mas pode recorrer. É um diagnóstico de exclusão.", "option_rationales": {"a": "Incorreta. O mesotelioma não regride espontaneamente.", "b": "Incorreta. Placas pleurais são lesões sólidas, fibróticas e calcificadas, não derrames.", "c": "Correta. Quadro clínico clássico de derrame benigno por exposição laboral.", "d": "Incorreta. Asbestose é a fibrose do parênquima pulmonar, não da pleura.", "e": "Incorreta. É uma massa parenquimatosa periférica causada por invaginação da pleura visceral, não é um derrame recorrente."}, "difficulty": "media", "tags": ["Pneumologia", "Medicina do Trabalho", "Asbesto", "BAPE"]}', 99, 'draft');
